report.query:
SELECT name, value FROM stats WHERE name GLOB '*heapprofd*' AND value != 0;
SELECT p.name, a.heap_name, COUNT(*) AS records, SUM(a.size) AS live_bytes, MIN(a.ts) AS first_ts, MAX(a.ts) AS last_ts FROM heap_profile_allocation a JOIN process p USING (upid) GROUP BY a.upid,a.heap_name;
WITH RECURSIVE live AS (
 SELECT callsite_id, SUM(size) AS bytes FROM heap_profile_allocation GROUP BY callsite_id HAVING SUM(size)>0
), stacks(origin, id, parent_id, frame_id, bytes) AS (
 SELECT l.callsite_id,c.id,c.parent_id,c.frame_id,l.bytes FROM live l JOIN stack_profile_callsite c ON c.id=l.callsite_id
 UNION ALL
 SELECT s.origin,c.id,c.parent_id,c.frame_id,s.bytes FROM stacks s JOIN stack_profile_callsite c ON c.id=s.parent_id
), modules AS (
 SELECT DISTINCT s.origin,s.bytes,m.name FROM stacks s JOIN stack_profile_frame f ON f.id=s.frame_id JOIN stack_profile_mapping m ON m.id=f.mapping
) SELECT name, SUM(bytes) AS inclusive_live_bytes FROM modules GROUP BY name ORDER BY inclusive_live_bytes DESC LIMIT 25;
WITH RECURSIVE live AS (
 SELECT callsite_id, SUM(size) AS bytes FROM heap_profile_allocation GROUP BY callsite_id HAVING SUM(size)>0
), stacks(origin, id, parent_id, frame_id, bytes) AS (
 SELECT l.callsite_id,c.id,c.parent_id,c.frame_id,l.bytes FROM live l JOIN stack_profile_callsite c ON c.id=l.callsite_id
 UNION ALL
 SELECT s.origin,c.id,c.parent_id,c.frame_id,s.bytes FROM stacks s JOIN stack_profile_callsite c ON c.id=s.parent_id
) SELECT f.name, f.rel_pc,m.name AS module,SUM(s.bytes) AS inclusive_live_bytes FROM stacks s JOIN stack_profile_frame f ON f.id=s.frame_id JOIN stack_profile_mapping m ON m.id=f.mapping GROUP BY f.id ORDER BY inclusive_live_bytes DESC LIMIT 65;

report.sampling_configuration:
buffers { size_kb: 65536 fill_policy: RING_BUFFER }
 duration_ms: 240000
 data_sources { config {
  name: "android.heapprofd"
  heapprofd_config {
   sampling_interval_bytes: 65536
   process_cmdline: "com.waterui.example.map"
   shmem_size_bytes: 16777216
   block_client: true
   continuous_dump_config { dump_interval_ms: 2000 }
  }
 } }

