#include <vulkan/vulkan.h>
#include <android/log.h>
#include <malloc.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#define CHECK(expr) do { VkResult result=(expr); if(result != VK_SUCCESS) { __android_log_print(ANDROID_LOG_FATAL,"CommandPoolRepro","%s failed: %d",#expr,result); abort(); } } while(0)
static void memory(const char *stage) {
 FILE *f=fopen("/proc/self/status","r"); if(!f) abort(); char line[256];
 while(fgets(line,sizeof(line),f)) if(!strncmp(line,"VmRSS:",6)) __android_log_print(ANDROID_LOG_INFO,"CommandPoolRepro","stage=%s %s",stage,line);
 fclose(f);struct mallinfo info=mallinfo();__android_log_print(ANDROID_LOG_INFO,"CommandPoolRepro","stage=%s malloc_used=%zu malloc_free=%zu",stage,(size_t)info.uordblks,(size_t)info.fordblks);
}
int main(void) {
 VkApplicationInfo app={.sType=VK_STRUCTURE_TYPE_APPLICATION_INFO,.apiVersion=VK_API_VERSION_1_1};
 VkInstanceCreateInfo ii={.sType=VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO,.pApplicationInfo=&app};VkInstance instance;CHECK(vkCreateInstance(&ii,0,&instance));
 uint32_t count=0;CHECK(vkEnumeratePhysicalDevices(instance,&count,0)); if(!count)abort();VkPhysicalDevice *physical=calloc(count,sizeof(*physical));CHECK(vkEnumeratePhysicalDevices(instance,&count,physical));VkPhysicalDevice gpu=physical[0];free(physical);
 vkGetPhysicalDeviceQueueFamilyProperties(gpu,&count,0);VkQueueFamilyProperties *families=calloc(count,sizeof(*families));vkGetPhysicalDeviceQueueFamilyProperties(gpu,&count,families);uint32_t family=0;while(family<count && !(families[family].queueFlags&VK_QUEUE_GRAPHICS_BIT))family++;if(family==count)abort();free(families);
 float priority=1;VkDeviceQueueCreateInfo qi={.sType=VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO,.queueFamilyIndex=family,.queueCount=1,.pQueuePriorities=&priority};VkDeviceCreateInfo di={.sType=VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO,.queueCreateInfoCount=1,.pQueueCreateInfos=&qi};VkDevice device;CHECK(vkCreateDevice(gpu,&di,0,&device));
 VkCommandPoolCreateInfo pi={.sType=VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO,.flags=VK_COMMAND_POOL_CREATE_TRANSIENT_BIT,.queueFamilyIndex=family};VkCommandPool pool;CHECK(vkCreateCommandPool(device,&pi,0,&pool));memory("device-only");
 VkCommandBuffer buffers[2640];VkCommandBufferAllocateInfo ai={.sType=VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO,.commandPool=pool,.level=VK_COMMAND_BUFFER_LEVEL_PRIMARY,.commandBufferCount=2640};CHECK(vkAllocateCommandBuffers(device,&ai,buffers));memory("2640-allocated");
 CHECK(vkResetCommandPool(device,pool,0));memory("reset-default");
 CHECK(vkResetCommandPool(device,pool,VK_COMMAND_POOL_RESET_RELEASE_RESOURCES_BIT));memory("reset-release-resources");
 vkFreeCommandBuffers(device,pool,2640,buffers);memory("free-command-buffers");
 vkDestroyCommandPool(device,pool,0);memory("destroy-pool");vkDestroyDevice(device,0);vkDestroyInstance(instance,0);return 0;
}
